result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/contrast/src/index.js", "content": "/**
 * WCAG 2.1 color contrast utilities.
 *
 * References:
 * - Relative luminance: https://www.w3.org/TR/WCAG21/#dfn-relative-luminance
 * - Contrast ratio:     https://www.w3.org/TR/WCAG21/#dfn-contrast-ratio
 * - Text contrast:      https://www.w3.org/TR/WCAG21/#contrast-minimum (1.4.3)
 * - Large text:         https://www.w3.org/TR/WCAG21/#contrast-enhanced (1.4.6)
 */

/**
 * Parse a hex color string to { r, g, b } with 8-bit integer channels.
 * Accepts #RGB, #RGBA, #RRGGBB and #RRGGBBAA (with or without the leading '#').
 *
 * @param {string} hex
 * @returns {{ r: number, g: number, b: number }}
 */
export function hexToRgb(hex) {
  if (typeof hex !== 'string') {
    throw new TypeError(`hexToRgb expects a string, got ${typeof hex}`);
  }

  let h = hex.trim().replace(/^#/, '');

  switch (h.length) {
    case 3: {
      if (!/^[0-9a-fA-F]{3}$/.test(h)) throw new Error(`Invalid hex color: "${hex}"`);
      const [r, g, b] = h.split('').map((c) => parseInt(c + c, 16));
      return { r, g, b };
    }
    case 4: {
      // 3-digit color plus alpha channel; alpha is ignored for luminance.
      if (!/^[0-9a-fA-F]{4}$/.test(h)) throw new Error(`Invalid hex color: "${hex}"`);
      const [r, g, b] = h.slice(0, 3).split('').map((c) => parseInt(c + c, 16));
      return { r, g, b };
    }
    case 6:
    case 8: {
      if (!new RegExp(`^[0-9a-fA-F]{${h.length}}$`).test(h)) {
        throw new Error(`Invalid hex color: "${hex}"`);
      }
      const r = parseInt(h.slice(0, 2), 16);
      const g = parseInt(h.slice(2, 4), 16);
      const b = parseInt(h.slice(4, 6), 16);
      return { r, g, b };
    }
    default:
      throw new Error(`Invalid hex color length (${h.length}): "${hex}"`);
  }
}

/**
 * WCAG 2.1 channel transfer function.
 * c is an 8-bit sRGB channel value; returns the linearized value in [0, 1].
 */
function channel(c) {
  const s = c / 255;
  // Exact thresholds and constants from the WCAG 2.1 definition.
  return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
}

/**
 * Relative luminance per WCAG 2.1:
 *   L = 0.2126 R + 0.7152 G + 0.0722 B
 * where R, G, B are linearized channel values.
 *
 * @param {string|{r:number,g:number,b:number}} color hex string or rgb object
 * @returns {number} relative luminance in [0, 1]
 */
export function relativeLuminance(color) {
  const rgb = typeof color === 'string' ? hexToRgb(color) : color;
  const [r, g, b] = [channel(rgb.r), channel(rgb.g), channel(rgb.b)];
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/**
 * Contrast ratio per WCAG 2.1:
 *   (L1 + 0.05) / (L2 + 0.05), where L1 is the lighter of the two luminances.
 * Rounded half-up to 2 decimal places.
 *
 * @param {string|{r:number,g:number,b:number}} a
 * @param {string|{r:number,g:number,b:number}} b
 * @returns {number} ratio in [1, 21]
 */
export function contrastRatio(a, b) {
  const la = relativeLuminance(a);
  const lb = relativeLuminance(b);
  const [lighter, darker] = la >= lb ? [la, lb] : [lb, la];
  const ratio = (lighter + 0.05) / (darker + 0.05);
  return Math.round(ratio * 100) / 100;
}

/**
 * Grade a contrast ratio against WCAG success criteria.
 *
 * Thresholds:
 *   - Normal text (< 18pt / < 14pt bold): AA >= 4.5, AAA >= 7
 *   - Large text (>= 18pt regular, or >= 14pt bold): AA >= 3, AAA >= 4.5
 *     (18pt ≈ 24px, 14pt bold ≈ 18.66px)
 *
 * @param {number} ratio contrast ratio (e.g. from contrastRatio)
 * @param {{ fontSize?: number, bold?: boolean }} [options]
 *   fontSize in CSS px, bold defaults to false.
 * @returns {'AAA'|'AA'|'AA-large'|'fail'}
 */
export function grade(ratio, { fontSize = 16, bold = false } = {}) {
  const LARGE_NORMAL = 24; // 18pt in px
  const LARGE_BOLD = 18.66; // 14pt bold in px (~18.66px)
  const isLarge = fontSize >= LARGE_NORMAL || (bold && fontSize >= LARGE_BOLD);

  if (!isLarge) {
    if (ratio >= 7) return 'AAA';
    if (ratio >= 4.5) return 'AA';
  } else {
    if (ratio >= 4.5) return 'AAA';
    if (ratio >= 3) return 'AA-large';
  }
  return 'fail';
}
