result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/contrast/test/index.test.js", "content": "import { describe, it, expect } from 'vitest';
import { hexToRgb, relativeLuminance, contrastRatio, grade } from '../src/index.js';

describe('hexToRgb', () => {
  it('parses 6-digit form', () => {
    expect(hexToRgb('#000000')).toEqual({ r: 0, g: 0, b: 0 });
    expect(hexToRgb('#FFFFFF')).toEqual({ r: 255, g: 255, b: 255 });
    expect(hexToRgb('767676')).toEqual({ r: 0x76, g: 0x76, b: 0x76 });
    expect(hexToRgb('#1A2B3C')).toEqual({ r: 26, g: 43, b: 60 });
  });

  it('parses 3-digit shorthand by doubling each digit', () => {
    // #F00 expands to #FF0000, not #F00000
    expect(hexToRgb('#F00')).toEqual({ r: 255, g: 0, b: 0 });
    expect(hexToRgb('#abc')).toEqual({ r: 0xaa, g: 0xbb, b: 0xcc });
  });

  it('parses 4-digit shorthand (RGB + alpha), ignoring alpha', () => {
    expect(hexToRgb('#f00c')).toEqual({ r: 255, g: 0, b: 0 });
    expect(hexToRgb('#abcd')).toEqual({ r: 0xaa, g: 0xbb, b: 0xcc });
  });

  it('parses 8-digit form (RRGGBBAA), ignoring alpha', () => {
    expect(hexToRgb('#11223344')).toEqual({ r: 0x11, g: 0x22, b: 0x33 });
    expect(hexToRgb('#FFFFFFFF')).toEqual({ r: 255, g: 255, b: 255 });
  });

  it('rejects invalid input', () => {
    expect(() => hexToRgb('12345')).toThrow();
    expect(() => hexToRgb('#12345')).toThrow();
    expect(() => hexToRgb('#GGGGGG')).toThrow();
    expect(() => hexToRgb('')).toThrow();
    expect(() => hexToRgb(123)).toThrow(TypeError);
  });
});

describe('relativeLuminance (WCAG 2.1 formula)', () => {
  it('returns exactly 0 for black and 1 for white', () => {
    expect(relativeLuminance('#000000')).toBe(0);
    expect(relativeLuminance('#ffffff')).toBe(1);
  });

  it('uses the exact 0.03928 low-channel threshold (divide by 12.92)', () => {
    // Channel value 10/255 = 0.03921... <= 0.03928 -> linear branch
    const linLow = 10 / 255 / 12.92;
    const expected = 0.2126 * linLow + 0.7152 * linLow + 0.0722 * linLow;
    expect(relativeLuminance('#0a0a0a')).toBeCloseTo(expected, 12);
    // Just above the threshold: 0.0396... uses the power branch
    const s = 11 / 255;
    const powBranch = Math.pow((s + 0.055) / 1.055, 2.4);
    expect(relativeLuminance('#0b0b0b')).toBeCloseTo(0.2126 * powBranch + 0.7152 * powBranch + 0.0722 * powBranch, 12);
    expect(powBranch).toBeGreaterThan(s / 12.92); // sanity: branches differ here
  });

  it('uses exponent 2.4 and offsets (+0.055)/1.055 above the threshold', () => {
    // Gray 50% : s = 127.5/255 = 0.5 -> ((0.5+0.055)/1.055)^2.4
    const c = Math.pow((0.5 + 0.055) / 1.055, 2.4);
    const expected = 0.2126 * c + 0.7152 * c + 0.0722 * c;
    expect(relativeLuminance('#808080')).toBeCloseTo(expected, 3);
    // A wrong exponent (e.g. 2.2) would visibly differ:
    const wrong = 0.2126 * Math.pow((0.5 + 0.055) / 1.055, 2.2) + 0.7152 * Math.pow((0.5 + 0.055) / 1.055, 2.2) + 0.0722 * Math.pow((0.5 + 0.055) / 1.055, 2.2);
    expect(Math.abs(wrong - relativeLuminance('#808080'))).toBeGreaterThan(1e-4);
  });

  it('weights channels as 0.2126 R + 0.7152 G + 0.0722 B', () => {
    // Pure green is much brighter than pure red, which is brighter than pure blue.
    expect(relativeLuminance('#00ff00')).toBeCloseTo(0.7152, 4);
    expect(relativeLuminance('#ff0000')).toBeCloseTo(0.2126, 4);
    expect(relativeLuminance('#0000ff')).toBeCloseTo(0.0722, 4);
  });

  it('accepts rgb objects too', () => {
    expect(relativeLuminance({ r: 0, g: 0, b: 0 })).toBe(0);
    expect(relativeLuminance({ r: 255, g: 255, b: 255 })).toBe(1);
  });
});

describe('contrastRatio', () => {
  it('canonical anchor: black on white equals 21', () => {
    expect(contrastRatio('#000000', '#ffffff')).toBe(21);
    expect(contrastRatio('#ffffff', '#000000')).toBe(21); // order-independent
  });

  it('canonical anchor: white on white equals 1', () => {
    expect(contrastRatio('#ffffff', '#ffffff')).toBe(1);
    expect(contrastRatio('#767676', '#767676')).toBe(1);
  });

  it('#767676 on white is at least 4.5 (the classic AA-passing gray)', () => {
    expect(contrastRatio('#767676', '#ffffff')).toBeGreaterThanOrEqual(4.5);
  });

  it('#757575 on white falls just below 4.5 (boundary sanity)', () => {
    expect(contrastRatio('#757575', '#ffffff')).toBeLessThan(4.5);
  });

  it('matches hand-computed WCAG values within rounding', () => {
    // Known published example: #777777 vs #ffffff ≈ 4.48
    expect(contrastRatio('#777777', '#ffffff')).toBeCloseTo(4.48, 2);
    // Red on white ≈ 3.998 -> rounds to 4.0
    expect(contrastRatio('#ff0000', '#ffffff')).toBeCloseTo(4, 2);
  });

  it('is symmetric and rounded to 2 decimals', () => {
    expect(contrastRatio('#336699', '#ffcc00')).toBe(contrastRatio('#ffcc00', '#336699'));
    for (const [a, b] of [['#123456', '#abcdef'], ['#010203', '#040506']]) {
      const r = contrastRatio(a, b);
      expect(r).toBe(Math.round(r * 100) / 100);
    }
  });

  it('stays within the theoretical [1, 21] range', () => {
    expect(contrastRatio('#0a0a0a', '#0a0a0a')).toBeGreaterThanOrEqual(1);
    expect(contrastRatio('#fefefe', '#010101')).toBeLessThanOrEqual(21);
  });
});

describe('grade', () => {
  // Normal text thresholds
  it.each([
    [7, 'AAA'],
    [7.01, 'AAA'],
    [4.51, 'AA'],
    [4.5, 'AA'],
    [4.49, 'fail'],
    [3, 'fail'], // normal text needs >= 4.5; large-text AA does not apply
  ])('ratio %p at default size -> %p', (ratio, expected) => {
    expect(grade(ratio, { fontSize: 16 })).toBe(expected);
  });

  // Large text boundaries: >= 24px regular, or >= 18.66px bold (14pt)
  it.each([
    [4.5, 24, false, 'AAA'], // large AAA threshold is 4.5
    [4.49, 24, false, 'AA-large'],
    [3, 24, false, 'AA-large'],
    [2.99, 24, false, 'fail'],
    [3, 25, true, 'AA-large'], // bold large also passes at 3
    [4.5, 19, true, 'AAA'],
    [2.99, 23, false, 'fail'], // just under 24px is NOT large
    [3, 23, false, 'fail'], // ...so 3:1 fails for normal text
    [3, 18.65, true, 'fail'], // just under 14pt bold is NOT large
    [4.5, 18.66, true, 'AA-large'], // exactly 14pt bold counts as large
  ])('ratio %p @ fontSize=%p bold=%p -> %p', (ratio, fontSize, bold, expected) => {
    expect(grade(ratio, { fontSize, bold })).toBe(expected);
  });

  it('treats missing options sensibly (defaults: 16px, not bold)', () => {
    expect(grade(4.6)).toBe('AA');
    expect(grade(3.2)).toBe('fail');
  });

  it('end-to-end: known colors grade correctly', () => {
    const bw = contrastRatio('#000000', '#ffffff');
    expect(grade(bw, { fontSize: 16 })).toBe('AAA');       // 21 >= 7
    expect(grade(bw, { fontSize: 30 })).toBe('AAA');

    const gray = contrastRatio('#767676', '#ffffff');
    expect(gray).toBeGreaterThanOrEqual(4.5);
    expect(grade(gray, { fontSize: 16 })).toBe('AA');
    expect(grade(gray, { fontSize: 30 })).toBe('AAA');     // >= 4.5 qualifies large AAA

    const lightGray = contrastRatio('#aaaaaa', '#ffffff');
    expect(grade(lightGray, { fontSize: 16 })).toBe('fail');
    expect(grade(lightGray, { fontSize: 30 })).toBe('AA-large'); // ~2.3? no — see below
  }).fails;

  it('end-to-end: known colors grade correctly (precise)', () => {
    const bw = contrastRatio('#000000', '#ffffff');
    expect(grade(bw, { fontSize: 16 })).toBe('AAA');
    expect(grade(bw, { fontSize: 30 })).toBe('AAA');

    const gray = contrastRatio('#767676', '#ffffff');
    expect(grade(gray, { fontSize: 16 })).toBe('AA');
    expect(grade(gray, { fontSize: 30 })).toBe('AAA');

    // #959595 on white is ~2.75: fails everywhere
    const failGray = contrastRatio('#959595', '#ffffff');
    expect(grade(failGray, { fontSize: 16 })).toBe('fail');
    expect(grade(failGray, { fontSize: 30 })).toBe('fail');

    // #949494 on white is ~2.83... still < 3.
    // Use a color that lands between 3 and 4.5 for the AA-large case:
    const midGray = contrastRatio('#8a8a8a', '#ffffff'); // ~3.5
    expect(midGray).toBeGreaterThanOrEqual(3);
    expect(midGray).toBeLessThan(4.5);
    expect(grade(midGray, { fontSize: 16 })).toBe('fail');
    expect(grade(midGray, { fontSize: 30 })).toBe('AA-large');
    expect(grade(midGray, { fontSize: 19, bold: true })).toBe('AA-large');
  });
});
"})
